const items = $input.all();
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

return items.map(item => {
  const raw = item.json.email;
  let emails = [];

  if (Array.isArray(raw)) {
    emails = raw;
  } else if (typeof raw === 'string') {
    const str = raw.trim();
    if (str.startsWith('[')) {
      try {
        const parsed = JSON.parse(str);
        if (Array.isArray(parsed)) emails = parsed;
      } catch (e) {
        // not valid JSON, fall through to delimiter split
      }
    }
    if (emails.length === 0 && str.length > 0) {
      emails = str.split(/[,;|\n]+/);
    }
  }

  emails = [...new Set(
    emails
      .map(e => String(e).trim().toLowerCase())
      .filter(e => e.length > 0 && emailRegex.test(e))
  )];

  return {
    json: {
      ...item.json,
      emailList: emails,
      emailCount: emails.length
    }
  };
});

