const original = $('Loop Over Items1').item.json;
const raw = ($json.output || $json.text || '').toString();
let selected = null;
let emailSubject = null;
let emailBody = null;

try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  selected = parsed.selected_email || null;
  emailSubject = parsed.email_subject ? String(parsed.email_subject).trim() : null;
  emailBody = parsed.email_body ? String(parsed.email_body).trim() : null;
} catch (e) {
  const match = raw.match(/[^\s"]+@[^\s"]+\.[^\s"]+/);
  if (match) selected = match[0];
}

return [{
  json: {
    ...original,
    selectedEmail: selected ? selected.trim().toLowerCase() : null,
    emailSubject,
    emailBody
  }
}];

// ---- CONFIG ---------------------------------------------------------------
const FROM_EMAIL = "contact@tritechit.online"; // must be a VERIFIED "Send mail as" alias in the Gmail account
const FROM_NAME = "TriTech";
const TEST_MODE = false; // true = send to TEST_TO; false = send to the selected lead email
const TEST_TO = "fahmid267@gmail.com";
const SUBJECT = "Cold Email Test"; // fallback subject if the AI subject is missing

// Node names (change here if you rename them)
const NODE_AGENT = "AI Agent"; // agent 2 (email writer)
const NODE_LOOP = "Loop Over Items1"; // original lead row
const NODE_VALID = "Has Valid Email?1"; // carries selectedEmail
const NODE_SIGNATURE = "Get Email Signature1";
// ---------------------------------------------------------------------------

// Read from a specific upstream node (works regardless of what sits directly before this node)
const fromNode = (name) => {
  try {
    return $(name).item.json;
  } catch (e) {
    try {
      return $(name).first().json;
    } catch (e2) {
      return {};
    }
  }
};

const lead = fromNode(NODE_LOOP);
const selectedEmail = fromNode(NODE_VALID).selectedEmail || lead.selectedEmail || null;

const to = TEST_MODE ? TEST_TO : selectedEmail;
if (!to) throw new Error("No recipient email found for this item");

const agency = lead.agency_name ? String(lead.agency_name).trim() : "";

// ---- Parse the personalized email written by agent 2 ------------------------
const agentJson = fromNode(NODE_AGENT);
const agentRaw = String(agentJson.output || agentJson.text || "").trim();

let aiSubject = "";
let aiBody = "";
let aiCompany = ""; // confirmed company name from agent 2 (web-search verified)
try {
  const cleaned = agentRaw.replace(/```json|```/gi, "").trim();
  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    const m = cleaned.match(/\{[\s\S]*\}/); // JSON object buried in extra text
    parsed = m ? JSON.parse(m[0]) : {};
  }
  aiSubject = parsed.email_subject ? String(parsed.email_subject) : "";
  aiBody = parsed.email_body ? String(parsed.email_body) : "";
  aiCompany = parsed.company_name ? String(parsed.company_name).replace(/\*\*/g, "").replace(/[\r\n]+/g, " ").trim() : "";
} catch (e) {
  // unparseable: fall back to the generic template below
}

aiSubject = aiSubject.replace(/[\r\n]+/g, " ").replace(/^["'\s]+|["'\s]+$/g, "").slice(0, 120);

// The greeting and sign-off are added here, so strip them if the AI included them anyway
aiBody = aiBody
  .replace(/\r\n/g, "\n")
  .replace(/^\s*(dear|hello|hi)\b[^\n]*\n+/i, "")
  .replace(/\n+\s*(kind|best|warm|many)\s+regards,?[\s\S]*$/i, "")
  .replace(/\n+\s*(sincerely|regards|thanks|thank you),?[\s\S]*$/i, "")
  .trim();

// Web search can leak citations/links into the text: keep link text, drop the URL (mailto links are left alone)
aiBody = aiBody
  .replace(/\s*\(\[[^\]]*\]\([^)]*\)\)/g, "")
  .replace(/\[([^\]]*)\]\((?!mailto)[^)]*\)/g, "$1")
  .trim();

// Company name to use in the email: the confirmed name from agent 2, or the spreadsheet name as a fallback
const displayName = aiCompany || agency;

// ---- Generic template (used only if the AI body is missing) -----------------
const genericBody = `Dear concerned,

We, TriTech, are reaching out to explore the possibility of establishing a strategic technology partnership with ${agency ? "@@AGENCY@@" : "your company"}.

TriTech provides software and technology solutions for businesses looking to develop, enhance, or scale their digital products. Our capabilities span software development, web and mobile applications, business automations, AI-driven solutions, and other tailored technology requirements.

We see potential for a complementary relationship between our organizations, particularly where software development and technical delivery can support broader client engagements and business opportunities. Depending on the nature of the engagement, we can work alongside existing teams or take responsibility for the technical development and delivery of a project, with the commercial structure tailored to the partnership.

You can learn more about TriTech and our capabilities at:
www.tritechit.online

If this aligns with your business model, we would be glad to arrange a brief conversation to explore potential areas of collaboration and discuss how such a partnership could be structured.

Kind regards,`;

const body = aiBody ? `Dear concerned,\n\n${aiBody}\n\nKind regards,` : genericBody;

// ---- Signature (same handling as before) ------------------------------------
let signature = "";
try {
  signature = $(NODE_SIGNATURE).first().json.signature || "";
} catch (e) {}

// replace the Gmail address wherever it appears in the signature
signature = signature.replace(/tritech\.it\.info(@|%40)gmail\.com/gi, "contact@tritechit.online");

// force the link whose visible text is the webmail address to use it
signature = signature.replace(/<a\b([^>]*)>([\s\S]*?)<\/a>/gi, (m, attrs, inner) =>
  /contact@tritechit\.online/i.test(inner)
    ? `<a${attrs.replace(/\s*href\s*=\s*("[^"]*"|'[^']*')/i, "")} href="mailto:contact@tritechit.online">${inner}</a>`
    : m
);

// ---- Plain text -> HTML (bold company name, hyperlinks, line breaks) --------
const escHtml = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const escRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

// 1) protect the email address and website so they can be turned into links after escaping
let text = body
  .replace(/contact@tritechit\.online/gi, "@@MAIL@@")
  .replace(/(?:https?:\/\/)?(?:www\.)?tritechit\.online\/?/gi, "@@SITE@@");

// 2) escape, then apply **bold** and the placeholders
let html = escHtml(text)
  .replace(/\*\*([^*\n]+?)\*\*/g, "<b>$1</b>")
  .replace(/@@AGENCY@@/g, () => `<b>${escHtml(agency)}</b>`)
  .replace(/@@SITE@@/g, '<a href="https://www.tritechit.online">www.tritechit.online</a>')
  .replace(/@@MAIL@@/g, '<a href="mailto:contact@tritechit.online">contact@tritechit.online</a>');

// 3) make sure the company name is bold on first mention, even if the AI forgot the ** markers
if (aiBody && agency.length >= 3) {
  const boldAgency = `<b>${escHtml(agency)}</b>`;
  if (!html.includes(boldAgency)) {
    const re = new RegExp(`(?<![\\w>])${escRegex(escHtml(agency))}(?![\\w<])`);
    html = html.replace(re, () => boldAgency);
  }
}

// 4) same check for the confirmed company name when it differs from the spreadsheet name
if (aiBody && displayName !== agency && displayName.length >= 3) {
  const boldDisplay = `<b>${escHtml(displayName)}</b>`;
  if (!html.includes(boldDisplay)) {
    const reDisplay = new RegExp(`(?<![\\w>])${escRegex(escHtml(displayName))}(?![\\w<])`);
    html = html.replace(reDisplay, () => boldDisplay);
  }
}

const htmlBody =
  '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;">' +
  html.replace(/\r?\n/g, "<br>\n") +
  "<br><br>" +
  signature +
  "</div>";

// ---- MIME / encoding (unchanged) --------------------------------------------
// RFC 2047 encoding so non-ASCII characters in headers survive
const encHeader = (s) =>
  /^[\x20-\x7E]*$/.test(s) ? s : `=?UTF-8?B?${Buffer.from(s, "utf-8").toString("base64")}?=`;

// Body as base64 (wrapped at 76 chars) so characters like ’ are safe
const bodyB64 = Buffer.from(htmlBody.replace(/\r?\n/g, "\r\n"), "utf-8")
  .toString("base64")
  .match(/.{1,76}/g)
  .join("\r\n");

const subject = aiSubject || SUBJECT;

const message = [
  `From: ${encHeader(FROM_NAME)} <${FROM_EMAIL}>`,
  `To: ${to}`,
  `Subject: ${encHeader(subject)}`,
  "MIME-Version: 1.0",
  "Content-Type: text/html; charset=UTF-8",
  "Content-Transfer-Encoding: base64",
  "",
  bodyB64,
].join("\r\n");

// base64url, as required by the Gmail API "raw" field
const raw = Buffer.from(message, "utf-8")
  .toString("base64")
  .replace(/\+/g, "-")
  .replace(/\//g, "_")
  .replace(/=+$/, "");

return {
  json: {
    ...lead,
    selectedEmail,
    emailSubject: subject,
    usedGenericFallback: !aiBody,
    raw,
  },
};

