={{ (() => {
  const today = $now.startOf('day');
  let d = DateTime.fromISO('2026-10-14', { zone: $now.zone }).startOf('day'); // first run day, change if needed
  if (d.weekday === 7) d = d.plus({ days: 1 });
  for (let i = 0; i < 5000 && d < today; i++) {
    d = d.plus({ days: 3 });                       // next run in the 3-day cycle
    if (d.weekday === 7) d = d.plus({ days: 1 });  // Sunday -> Monday, cycle continues from Monday
  }
  return d.hasSame(today, 'day');
})() }}
